mapper.select:
SELECT a.id, a.employee_id AS employeeId, e.emp_no AS empNo, e.name AS employeeName, d.name AS deptName, a.att_date AS attDate, a.status, a.remark, a.update_time AS updateTime FROM hr_attendance a JOIN hr_employee e ON e.id = a.employee_id AND e.deleted = 0 LEFT JOIN sys_dept d ON d.id = e.dept_id AND d.deleted = 0 WHERE a.deleted = 0
AND a.employee_id = #{employeeId}
AND a.att_date >= #{from}
AND a.att_date <= #{to}
ORDER BY a.att_date DESC, a.id DESC

SELECT pd.id, pd.period_id AS periodId, w.period, pd.employee_id AS employeeId, e.emp_no AS empNo, e.name AS employeeName, pd.work_order_id AS workOrderId, pd.work_order_no AS workOrderNo, pd.material_id AS materialId, m.code AS materialCode, m.name AS materialName, pd.process_name AS processName, pd.qty, pd.unit_price AS unitPrice, pd.amount, pd.create_time AS createTime FROM hr_piece_wage_detail pd JOIN hr_piece_wage w ON w.id = pd.period_id AND w.deleted = 0 LEFT JOIN hr_employee e ON e.id = pd.employee_id AND e.deleted = 0 LEFT JOIN base_material m ON m.id = pd.material_id AND m.deleted = 0 WHERE pd.deleted = 0 AND pd.period_id = #{periodId}
AND pd.employee_id = #{employeeId}
ORDER BY pd.id DESC
